class FoodRatings(foods:Array<String>,cuisineValues:Array<String>,ratingValues:IntArray){private val cuisines=HashMap<String,String>();private val ratings=HashMap<String,Int>();private val ranked=HashMap<String,java.util.TreeSet<String>>();private val order=Comparator<String>{a,b->val compare=ratings[b]!!.compareTo(ratings[a]!!);if(compare!=0)compare else a.compareTo(b)};init{for(i in foods.indices){cuisines[foods[i]]=cuisineValues[i];ratings[foods[i]]=ratingValues[i];ranked.getOrPut(cuisineValues[i]){java.util.TreeSet(order)}.add(foods[i])}}fun changeRating(food:String,newRating:Int){val set=ranked[cuisines[food]]!!;set.remove(food);ratings[food]=newRating;set.add(food)}fun highestRated(cuisine:String):String=ranked[cuisine]!!.first()}
